<?php use Aurelle\Database as DB; if ($section==='users'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('role_revoke',$rid,$section) ?><select class="input" name="role"><option value="agent">Agent permission</option><option value="support">Support permission</option></select><button class="button small outline">Revoke role</button></form>
<?php elseif (in_array($section,['leads','valuations'])): ?><?php if ($section==='leads'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('lead_assign',$rid,$section) ?><select class="input" name="agent_id"><?php foreach ($data['approvedAgents'] as $a): ?><option value="<?= $a['user_id'] ?>"><?= e($a['name']) ?></option><?php endforeach ?></select><button class="button small">Assign lead</button></form><details><summary>Assignment history</summary><?php foreach (DB::all('SELECT * FROM lead_assignment_history WHERE lead_id=? ORDER BY id DESC',[$rid]) as $h): ?><p class="tiny">Agent #<?= $h['agent_id'] ?> · Actor #<?= $h['actor_id'] ?> · <?= e($h['created_at']) ?> UTC</p><?php endforeach ?></details><?php endif ?>
<?php elseif ($section==='viewings'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('viewing_state',$rid,$section) ?><select class="input" name="state"><option>confirmed</option><option>cancelled</option><option>completed</option><option>no_show</option></select><button class="button small">Record appointment status</button></form>
<?php elseif ($section==='proposals'): ?><p class="tiny">Agreement in principle only; no ownership transfer.</p><?php foreach (DB::all('SELECT * FROM proposal_revisions WHERE proposal_id=? ORDER BY id',[$rid]) as $rev): ?><p class="tiny"><?= money($rev['amount_minor']) ?> · <?= e($rev['terms']) ?> · <?= e($rev['created_at']) ?></p><?php endforeach ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('proposal_state',$rid,$section) ?><select class="input" name="state"><option>acknowledged</option><option>rejected</option></select><button class="button small">Record status</button></form>
<?php elseif ($section==='pricing'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('price_review',$rid,$section) ?><select class="input" name="state"><option>approved</option><option>rejected</option></select><button class="button small">Review price request</button></form>
<?php elseif ($section==='providers'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('provider_review',$rid,$section) ?><select class="input" name="state"><option>approved</option><option>rejected</option><option>archived</option></select><button class="button small">Review provider</button></form>
<?php elseif ($section==='business'): ?><form action="/admin/action" method="post"><?= adminHidden('business',0,$section) ?><input type="hidden" name="setting_key" value="<?= e($r['setting_key']) ?>"><label class="field"><span><?= e(str_replace('_',' ',$r['setting_key'])) ?></span><textarea name="setting_value" required><?= e($r['setting_value']) ?></textarea></label><button class="button small">Update business details</button></form>
<?php elseif ($section==='catalog'): ?><form action="/admin/action" method="post"><?= adminHidden('service_catalog',$rid,$section) ?><label class="field"><span>Service name</span><input name="name" value="<?= e($r['name']) ?>" required></label><label class="field"><span>Description</span><textarea name="description" required><?= e($r['description']) ?></textarea></label><label class="field"><span>Indicative price ($)</span><input name="price" type="number" step=".01" value="<?= e($r['price_minor']/100) ?>" required></label><label><input type="checkbox" name="active" <?= $r['active']?'checked':'' ?>> Active</label><button class="button small">Save service</button></form>
<?php elseif ($section==='neighborhoods'): ?><form action="/admin/action" method="post"><?= adminHidden('neighborhood',$rid,$section) ?><label class="field"><span>Name</span><input name="name" value="<?= e($r['name']) ?>" required></label><label class="field"><span>City</span><input name="city" value="<?= e($r['city']) ?>" required></label><label class="field"><span>Guide</span><textarea name="description" required><?= e($r['description']) ?></textarea></label><button class="button small">Save guide</button></form>
<?php endif ?>
